/**
 * Unbuffed base stats for a career at a given level (exact server values,
 * levels 1-80).
 */
export function getCareerBaseStats(
  career: Career | null | undefined,
  level: number,
): BaseStats {
  const byLevel = career ? CAREER_BASE_STATS_BY_LEVEL[career] : undefined;
  if (!byLevel) return ZERO;
  const clamped = Math.min(80, Math.max(1, Math.round(level)));
  return byLevel[clamped] ?? ZERO;
}
